def element_lower_meaning(el):
    m = {"Fire":"passion, creativity, and drive","Water":"emotion, intuition, and relationships","Air":"thought, communication, and intellect","Earth":"material world, stability, and practical matters"}
    return m.get(el, "practical matters")


