def slugify_card(title):
    import re as _re
    s = title.lower()
    cards_to_check = list(MAJOR_ARCANA_DB.keys()) + list(MINOR_DB.keys())
    for card in cards_to_check:
        if card.replace("-"," ") in s or card.split("-")[0] in s:
            return card
    s = _re.sub(r"(the|tarot|card|meaning|in|thoth|deck|of|and|for|a|to)", "", s)
    s = _re.sub(r"[\s_-]+", "-", s).strip("-")
    return s


def slugify(s):
    import re as _re
    s = s.lower()
    s = _re.sub(r"[^\w\s-]", "", s)
    s = _re.sub(r"[\s_]+", "-", s).strip("-")
    return s


def generate_full_article(entry):
    n = entry["n"]
    title = entry["title"]
    keyword = entry["keyword"]
    section = entry["section"]
    tags = entry["tags"]

    s_slug = slugify(title)
    seo_title = title[:60] if len(title) <= 60 else title[:57] + "..."
