    seo_desc = "Discover the meaning of {} in the Thoth Tarot deck. Expert guidance, symbolism analysis, and practical reading advice.".format(" ".join(kw_words))[:160]

    # Genera corpo — matching flessibile
    kw_lower = keyword.lower().replace("-", " ")
    body = None  # default
    
    # Major Arcana match (senza trattini)
    major_match = any(k.replace("-"," ") in kw_lower for k in MAJOR_ARCANA_DB)
    
    # Minor Arcana match (senza trattini, con alias pentacles→disks)
    minor_keys_alt = list(MINOR_DB.keys()) + ["pentacles"]  # pentacles = Disks
    minor_match = any(k.replace("-"," ") in kw_lower for k in minor_keys_alt)
    
    if major_match:
        body = fill_major_article(entry)
    elif minor_match:
        body = fill_minor_article(entry)
    elif "spread" in title.lower() or "full moon" in kw_lower:
        body = fill_spread_article(entry)
